<script setup>
import {computed,ref} from 'vue';import {ElMessage} from 'element-plus';import PageHeader from '../../components/common/PageHeader.vue';import {createDraft} from '../../utils/customize.js';import {submitCustomization} from '../../api/customize.js'
const draft=computed(()=>{try{return JSON.parse(sessionStorage.getItem('customizeDraft'))||createDraft()}catch{return createDraft()}});const submitting=ref(false);async function submit(){submitting.value=true;await submitCustomization(draft.value);ElMessage.success('定制需求已提交');setTimeout(()=>location.href='/workspace',400)}
</script>
<template><div class="page-shell"><div class="container confirm"><PageHeader title="确认定制需求" description="提交前请核对以下信息，设计师会在收到需求后与您联系。" :breadcrumbs="['首页','在线定制','确认需求']"/><div class="confirm-sheet"><section><h2>联系与空间</h2><dl><dt>联系人</dt><dd>{{draft.contact||'未填写'}}</dd><dt>联系电话</dt><dd>{{draft.phone||'未填写'}}</dd><dt>定制空间</dt><dd>{{draft.space}}</dd><dt>房屋类型</dt><dd>{{draft.houseType||'未选择'}}</dd></dl></section><section><h2>方案偏好</h2><dl><dt>风格</dt><dd>{{draft.style}}</dd><dt>材料</dt><dd>{{draft.materials.join('、')||'由设计师建议'}}</dd><dt>预算</dt><dd>{{draft.budget||'未选择'}}</dd><dt>期望交付</dt><dd>{{draft.deliveryDate||'沟通后确定'}}</dd></dl></section><section class="wide"><h2>补充信息</h2><p>{{draft.description||'暂无补充说明'}}</p></section></div><div class="confirm-actions"><el-button @click="$router.back()">返回修改</el-button><el-button type="primary" :loading="submitting" @click="submit">提交定制需求</el-button></div></div></div></template>
<style scoped>.confirm{max-width:900px}.confirm-sheet{display:grid;grid-template-columns:1fr 1fr;background:#fff;border:1px solid var(--c-border)}.confirm-sheet section{padding:28px 32px}.confirm-sheet section+section{border-left:1px solid var(--c-border)}.confirm-sheet .wide{grid-column:1/-1;border-left:0;border-top:1px solid var(--c-border)}.confirm-sheet h2{font:500 20px var(--font-display)}dl{display:grid;grid-template-columns:90px 1fr;gap:12px;margin:20px 0 0}dt{color:var(--c-muted)}dd{margin:0}.confirm-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}@media(max-width:650px){.confirm-sheet{grid-template-columns:1fr}.confirm-sheet section+section{border-left:0;border-top:1px solid var(--c-border)}.confirm-sheet .wide{grid-column:auto}}</style>
